def dedupe_contacts(rows):
    """Merge duplicate contact rows into one record per person.

    See the module-level rules in the accompanying notes for matching details.
    Output is ordered by each person's earliest row in the input.
    """

    def normalize_email(raw):
        e = raw.strip().lower()
        if e.count("@") == 1:
            local, domain = e.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.replace(".", "")
                local = local.split("+", 1)[0]
                e = f"{local}@gmail.com"
        return e

    def is_valid_email(e):
        if e.count("@") != 1:
            return False
        local, domain = e.split("@")
        if not local:
            return False
        return "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(raw):
        digits = "".join(ch for ch in raw if "0" <= ch <= "9")
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        return digits if len(digits) == 10 else ""

    # Steps 1-4: normalize, validate, and drop rows with no usable contact.
    prepared = []  # (input_index, row, valid_email_or_"", valid_phone_or_"")
    for idx, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        email = email if is_valid_email(email) else ""
        phone = normalize_phone(row.get("phone", ""))
        if not email and not phone:
            continue
        prepared.append((idx, row, email, phone))

    # Step 5: union-find so matching is transitive.
    # The root of each set is always its smallest input index, so sorting
    # roots later orders people by their earliest row.
    parent = {idx: idx for idx, _, _, _ in prepared}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            lo, hi = min(ra, rb), max(ra, rb)
            parent[hi] = lo

    email_seen = {}
    phone_seen = {}
    for idx, row, email, phone in prepared:
        if email:
            if email in email_seen:
                union(email_seen[email], idx)
            else:
                email_seen[email] = idx
        if phone:
            last = row.get("last_name", "").strip().lower()
            if last:
                key = (phone, last)
                if key in phone_seen:
                    union(phone_seen[key], idx)
                else:
                    phone_seen[key] = idx

    groups = {}
    for idx, row, email, phone in prepared:
        groups.setdefault(find(idx), []).append((idx, row, email, phone))

    def latest_value(member_values):
        """member_values: list of (input_index, row, value).
        Returns the value from the most recently updated row with a non-empty
        value; ties go to the earlier input row. Returns "" if none."""
        cands = [(i, r["updated"], v) for i, r, v in member_values if v]
        if not cands:
            return ""
        return max(cands, key=lambda c: (c[1], -c[0]))[2]

    # Steps 6-7: build one output record per group, in order of earliest row.
    result = []
    for root in sorted(groups):
        members = groups[root]

        first_name = latest_value(
            [(i, r, r.get("first_name", "").strip()) for i, r, _, _ in members]
        )
        last_name = latest_value(
            [(i, r, r.get("last_name", "").strip()) for i, r, _, _ in members]
        )
        zip_code = latest_value(
            [(i, r, r.get("zip", "").strip()) for i, r, _, _ in members]
        )
        email = latest_value([(i, r, e) for i, r, e, _ in members])
        phone = latest_value([(i, r, p) for i, r, _, p in members])

        tag_set = set()
        for _, r, _, _ in members:
            for t in r.get("tags", "").split(";"):
                t = t.strip().lower()
                if t:
                    tag_set.add(t)

        opted_out = "Y" if any(
            r.get("opted_out", "").strip().upper() == "Y" for _, r, _, _ in members
        ) else "N"

        updated = max(r["updated"] for _, r, _, _ in members)

        result.append({
            "first_name": first_name,
            "last_name": last_name,
            "email": email,
            "phone": phone,
            "zip": zip_code,
            "tags": ";".join(sorted(tag_set)),
            "opted_out": opted_out,
            "updated": updated,
        })

    return result
